    },
    {
      "card_ids": ["C02"],
      "claim": "A 1-benzylpiperidine ethylamide showed significant accumulation in monkey brain, directly analogous to the query's benzylpiperidine-methyl linker and supporting CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A 1-benzylpiperidine benzamide showed significant and lasting high brain uptake in mice, supporting the query's combination of a dimethoxyaromatic system and 1-benzylpiperidine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Org-25543, a dimethoxybenzamide with a basic amine, readily crossed the BBB with a free brain/plasma ratio of ~0.5, supporting the query's dimethoxyaromatic and basic amine features.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule contains a 1-benzylpiperidine moiety and a dimethoxyaromatic tetralone, both features strongly associated with CNS penetration in the provided evidence. Multiple structurally related N-benzylpiperidine compounds show high brain uptake, favorable brain-to-blood ratios, and PET imaging accumulation. The prediction is pass with high confidence.",
